final case class Hop(name: String, at: Instant = Instant.now())
final case class Traced[T](payload: T, hops: Vector[Hop] = Vector.empty)

def via[T](t: Traced[T], component: String): Traced[T] =
  t.copy(hops = t.hops :+ Hop(component))   // O(1) amortized, structural sharing

